scripts.王佐对话.txt:
// 和王佐对话

	If ($Event == 530) @Event530;
	Return;
	
@Event530:	
	SetNpcKind("张琳心", 1);
	PlayerGoto(5, 70);
	SetPlayerDir(1);
	NpcGoto("张琳心", 5, 71);
	SetNpcDir("张琳心", 2);
	SetNpcKind("张琳心", 3);
	Say("独孤剑：王将军！", 1);
	Say("王佐：独孤公子看来好了很多了。在下正等着两位呢！", 63);
	Say("张琳心：王将军有什么事吗？", 21):
	Say("王佐：两位此行的事情已经办完，是否打算回江南？", 63);
	Say("独孤剑：在下的确准备回衡山，出来得太久了，本派有许多的事情尚未打点。张姑娘也想回临安看她哥哥。", 2);
	Say("王佐：如此甚好。在下，想拜托二位顺路去一趟洞庭湖。", 63);
	Say("独孤剑：洞庭湖？", 8);
	Say("王佐：此事说来话长……", 63);
	NpcGoto("王佐", 3, 73);
	SetNpcDir("王佐", 1);
	Say("王佐：十年前，钟相在洞庭湖起兵，自称楚王，起义军拥兵十余万，南抗赵宋，北抵金兵。后来楚王被杀，义军残部推举龙阳杨幺为领袖，即后来的大圣天王。大圣天王大公无私，立楚王少子钟子仪为太子。义军发展迅猛，朝廷恐慌，多次派兵镇压都惨败而归。", 63);
	SetNpcKind("张琳心", 1);
	PlayerGoto(4, 72);
	SetPlayerDir(1);
	NpcGoto("张琳心", 3, 71);
	SetNpcDir("张琳心", 0);
	Say("独孤剑：这些在下也略有所闻。", 1);
	Say("王佐：五年前，朝廷将岳元帅调去洞庭湖剿灭义军。天王的部队被打得溃不成军，天王和太子被俘后也遭朝廷杀害。义军被镇压后元气大伤，所剩弟兄不足十之一二，只有天王的少公子杨瑛在外学艺，幸免遇难。少公子得知惨讯，连夜赶回洞庭湖，重新聚集散落四处的弟兄，组织了天王帮。帮主武艺高强，胆识过人，天王帮在他的带领下，日渐兴盛。", 63);
	Sleep(500);
	Say("王佐：帮主日夜不忘岳元帅杀父之仇，岳家军和义军更是仇深似海。于是，我便自愿潜伏到岳营中，准备刺杀岳元帅。", 63);
	Say("独孤剑：王将军你？", 6);
	SetNpcDir("王佐", 5);
	Say("王佐：不错！我便是天王帮的前使！", 63);
	Say("独孤剑：那为何王将军……", 1);
	Say("张琳心：我猜想一定是王将军接近岳元帅后，发现岳元帅乃是一个精忠报国、顶天立地的大英雄，于是反而被岳元帅折服了，对吗？", 21);
	Say("王佐：不错，岳元帅光明磊落，一心只为恢复我大宋河山，乃是民族的栋梁！我王佐对元帅是心悦诚服，又如何能够蓄意加害？", 63);
	Say("独孤剑：王将军深明大义，也不愧是堂堂正正的汉子！", 1);
	Say("王佐：唉！只可惜帮主未能理解王佐的苦心，依然执意要对元帅不利，最近，帮主又策谋了一个计划……唉，王佐身处其中，实感左右为难！", 63);
	Say("独孤剑：我们能为将军做点什么呢？", 1);
	Say("王佐：我想请二位去洞庭湖天王帮总坛，向帮主转告王佐的心意，并劝说帮主打消刺杀岳元帅的念头。帮主终归是明大义之人，以两位的大智大勇，我相信一定能够成功。", 63);
	Say("独孤剑：将军放心，独孤剑一定竭尽所能化解贵帮与岳元帅之间的仇怨！", 2);
	Say("王佐：多谢独孤少侠，我果然没有看错人！此外，帮主一直在寻找一幅“山河社稷图”，此图标明了中原的各处要隘，是一幅极为重要的地图。我听闻帮主已经得到，如有可能，少侠要劝说帮主将此图交给岳元帅，以助元帅收复中原的大业。", 63);
	Say("张琳心：“山河社稷图”？怎会落到天王帮手中……", 25);
	Say("王佐：天王帮总坛防范甚严，要进总坛，须核对口令，两位切切要记住口令。", 63);
	Say("王佐：“大圣镇番妖”对“天王盖地虎”；“华山三千丈”对“洞庭八百里”，记住了么？", 63);
	Say("独孤剑：在下记住了。事关紧要，琳儿，我们即刻启程。", 1);
	Say("王佐：少侠的身体……", 63);
	Say("独孤剑：不妨事，我已经恢复得差不多了。", 2);
	Say("王佐：那就有劳独孤少侠和张姑娘了，我即刻备船送二位启程。", 63);
	SetNpcKind("张琳心", 3);
	FadeOut();
	DelNpc("王佐");
	SaveNpc();
	SaveObj();
	StopMusic();
	PlayMusic("西山.mp3");
	LoadMap("map096_湖口村.map");
	LoadNpc("map096.npc");
	LoadObj("map096.obj");
	SetPlayerPos(3, 43);
	SetPlayerDir(5);
	SetNpcKind("张琳心", 1);
	SetNpcPos("张琳心", 3, 44);
	SetNpcDir("张琳心", 5);
	SetNpcKind("张琳心", 3);
	SetNpcRelation("张琳心", 0);
	SetNpcScript("张琳心", "张琳心对话.txt");
	Say("经过几个月的舟车劳顿，独孤剑和张琳心终于来到了八百里洞庭湖畔。");
	FadeIn();
	Say("独孤剑：这里应该就是湖口村了吧。", 1);
	Assign($Event, 540);
	Memo("独孤剑和张琳心在朱仙镇码头见到王佐，他拜托二人前往洞庭湖天王帮说服帮主不要与岳飞作对，三人辞别后，独孤剑和张琳心坐船来到了洞庭湖畔的湖口村。");
	Return;

